/// BrainFlowException class to notify about errors
class BrainFlowException : public std::exception
{

public:
    /// exit code returned from low level API
    int exit_code;

    explicit BrainFlowException (const char *msg, int exit_code) : std::exception ()
    {
        msg_ = std::string (msg) + std::to_string (exit_code);
        this->exit_code = exit_code;
    }

    virtual ~BrainFlowException () throw ()
    {
    }

    virtual const char *what () const throw ()
    {
        return msg_.c_str ();
    }

protected:
    std::string msg_;
};

struct BrainFlowInputParams
{
    std::string serial_port;
    std::string mac_address;
    std::string ip_address;
    std::string ip_address_aux;
    std::string ip_address_anc;
    int ip_port;
    int ip_port_aux;
    int ip_port_anc;
    int ip_protocol;
    std::string other_info;
    int timeout;
    std::string serial_number;
    std::string file;
    std::string file_aux;
    std::string file_anc;
    int master_board;

    BrainFlowInputParams ()
    {
        serial_port = "";
        mac_address = "";
        ip_address = "";
        ip_address_aux = "";
        ip_address_anc = "";
        ip_port = 0;
        ip_port_aux = 0;
        ip_port_anc = 0;
        ip_protocol = 0;
        other_info = "";
        timeout = 0;
        serial_number = "";
        file = "";
        file_aux = "";
        file_anc = "";
        master_board = (int)BoardIds::NO_BOARD;
    }

    // default copy constructor and assignment operator are ok, need less operator to use in map
    bool operator< (const struct BrainFlowInputParams &other) const
    {
        return std::tie (serial_port, mac_address, ip_address, ip_address_aux, ip_address_anc,
                   ip_port, ip_port_aux, ip_port_anc, ip_protocol, other_info, timeout,
                   serial_number, file, file_aux, file_anc, master_board) <
            std::tie (other.serial_port, other.mac_address, other.ip_address, other.ip_address_aux,
                other.ip_address_anc, other.ip_port, other.ip_port_aux, other.ip_port_anc,
                other.ip_protocol, other.other_info, other.timeout, other.serial_number, other.file,
                other.file_aux, other.file_anc, other.master_board);
    }

    bool operator> (const struct BrainFlowInputParams &other) const
    {
        return (!(*this < other)) && ((*this != other));
    }

    bool operator== (const struct BrainFlowInputParams &other) const
    {
        return (!(*this < other)) && (!(other < *this));
    }

    bool operator!= (const struct BrainFlowInputParams &other) const
    {
        return !(*this == other);
    }
};

struct BrainFlowModelParams
{
    int metric;
    int classifier;
    std::string file;
    std::string other_info;
    std::string output_name;
    int max_array_size;

    BrainFlowModelParams (int metric, int classifier)
    {
        this->metric = metric;
        this->classifier = classifier;
        file = "";
        other_info = "";
        output_name = "";
        max_array_size = 8192;
    }

    // default copy constructor and assignment operator are ok, need less operator to use in map
    bool operator< (const struct BrainFlowModelParams &other) const
    {
        return std::tie (metric, classifier, file, other_info, output_name, max_array_size) <
            std::tie (other.metric, other.classifier, other.file, other.other_info, output_name,
                max_array_size);
    }
};

