import random
import string
from typing import List

# Data type: arbitrary string (null-terminated when used as C-string)
# Goal: Produce interesting, valid strings that exercise different code paths in stubs:
# - Logging messages (printf-like), JSON params, streamer URIs, filenames, IPs/MACs, commands
# - Small to moderate size, ASCII/Unicode mix, edge cases (empty, long, special chars)
# - Deterministic with seed, bounded to <= 4096 bytes

MAX_LEN = 1024  # keep individual piece sizes moderate; overall <= 4096


def _rng(seed: int) -> random.Random:
    return random.Random(seed)


def _weighted_choice(r: random.Random, items: List[str], weights: List[float]) -> str:
    # simple weighted selection
    total = sum(weights)
    x = r.uniform(0, total)
    upto = 0.0
    for item, w in zip(items, weights):
        if upto + w >= x:
            return item
        upto += w
    return items[-1]


def _rand_int(r: random.Random, a: int, b: int) -> int:
    return r.randint(a, b)


def _rand_ascii(r: random.Random, n: int) -> str:
    alphabet = string.ascii_letters + string.digits + " _-.,:/@+%[]{}()#|<>?=\t\n\r"
    return ''.join(r.choice(alphabet) for _ in range(n))


def _rand_unicode(r: random.Random, n: int) -> str:
    # Mix of BMP ranges commonly safe in UTF-8 handling
    ranges = [
        (0x00A0, 0x00FF),  # Latin-1 supplement
        (0x0100, 0x017F),  # Latin Extended-A
        (0x0400, 0x04FF),  # Cyrillic
        (0x0370, 0x03FF),  # Greek
        (0x0600, 0x06FF),  # Arabic
        (0x0900, 0x097F),  # Devanagari
        (0x4E00, 0x9FFF),  # CJK Unified Ideographs
        (0x2000, 0x206F),  # General Punctuation
        (0x2190, 0x21FF),  # Arrows
    ]
    s = []
    for _ in range(n):
        lo, hi = r.choice(ranges)
        cp = r.randint(lo, hi)
        # avoid surrogate range
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0xE000
        s.append(chr(cp))
    return ''.join(s)


def _random_ip(r: random.Random) -> str:
    return '.'.join(str(_rand_int(r, 0, 255)) for _ in range(4))


def _random_multicast_ip(r: random.Random) -> str:
    # 224.0.0.0 to 239.255.255.255
    a = _rand_int(r, 224, 239)
    b = _rand_int(r, 0, 255)
    c = _rand_int(r, 0, 255)
    d = _rand_int(r, 0, 255)
    return f"{a}.{b}.{c}.{d}"


def _random_port(r: random.Random) -> int:
    return _rand_int(r, 1, 65535)


def _random_mac(r: random.Random) -> str:
    return ':'.join(f"{_rand_int(r,0,255):02x}" for _ in range(6))


def _random_filename(r: random.Random) -> str:
    bases = ["model.onnx", "config.json", "data.brd", "log.txt", "session.bf", "tmp.bin"]
    dirs = ["/tmp", "/var/tmp", ".", "./out", "./logs", "C:/temp", "D:/work"]
    if r.random() < 0.5:
        name = r.choice(bases)
    else:
        stem = _rand_ascii(r, _rand_int(r, 3, 12))
        ext = r.choice([".json", ".txt", ".onnx", ".bin", ".cfg", ".dat"])    
        name = stem + ext
    return r.choice(dirs) + "/" + name


def _random_streamer_uri(r: random.Random) -> str:
    # Supported: file://%file%:w|a and streaming_board://%multicast_ip%:%port%
    if r.random() < 0.5:
        mode = r.choice(['w', 'a'])
        return f"file://{_random_filename(r)}:{mode}"
    else:
        return f"streaming_board://{_random_multicast_ip(r)}:{_random_port(r)}"


def _random_json_params(r: random.Random) -> str:
    metric = r.randint(0, 2)
    classifier = r.randint(0, 2)
    other = _rand_ascii(r, _rand_int(r, 0, 40)).replace('"', '_')
    filev = _random_filename(r)
    return (
        '{' +
        f'"metric":{metric},"classifier":{classifier},"file":"{filev}","other_info":"{other}"' +
        '}'
    )


def _random_board_config(r: random.Random) -> str:
    # Simulate simple command-like strings some boards accept
    cmds = [
        "daisy on", "daisy off", "gain set 24", "test signal on", "test signal off",
        "chan 1 on", "chan 2 off", "reset", "sync", "set impedance 1",
    ]
    if r.random() < 0.6:
        return r.choice(cmds)
    # Fallback arbitrary but short tokenized string
    tokens = [
        "set", "get", "mode", "rate", "filter", "lp", "hp", "bp", "bs", "notch",
        _rand_ascii(r, _rand_int(r, 1, 6)), str(_rand_int(r, 1, 500))
    ]
    r.shuffle(tokens)
    s = ' '.join(tokens[:_rand_int(r, 2, min(6, len(tokens)))])
    return s[:128]


def _random_log_message(r: random.Random) -> str:
    parts = []
    parts.append(_rand_ascii(r, _rand_int(r, 5, 30)))
    if r.random() < 0.5:
        parts.append("%d")
        parts.append(str(_rand_int(r, -1000, 1000)))
    if r.random() < 0.5:
        parts.append("%s")
        parts.append(_rand_ascii(r, _rand_int(r, 3, 10)))
    if r.random() < 0.3:
        parts.append("\\n")
    return ' '.join(parts)[:256]


def _random_ip_config_snippet(r: random.Random) -> str:
    ip = _random_ip(r)
    port = _random_port(r)
    aux = _random_ip(r)
    mac = _random_mac(r)
    proto = r.choice([0,1,2])
    return f"ip={ip};port={port};aux={aux};mac={mac};proto={proto}"


def _prebaked_cases() -> List[str]:
    return [
        "",  # empty
        "{}",  # empty JSON
        "{\"metric\":0,\"classifier\":0}",
        "file:///tmp/out.txt:w",
        "streaming_board://224.0.0.1:12345",
        "%s %d",
        "[1,2,3]",
        "true",
        "null",
        "Unicode: π Δ 中文 العربية",
    ]


def generate(seed: int) -> bytes:
    r = _rng(seed)

    # Choose a scenario to target specific stub usages
    scenarios = [
        "json_params",
        "streamer_uri",
        "filename",
        "board_config",
        "log_message",
        "ip_config",
        "ascii_blob",
        "unicode_blob",
        "prebaked",
    ]
    weights = [2, 2, 1.5, 1.5, 2, 1.5, 1.5, 1.0, 1.0]
    scenario = _weighted_choice(r, scenarios, weights)

    if scenario == "json_params":
        s = _random_json_params(r)
    elif scenario == "streamer_uri":
        s = _random_streamer_uri(r)
    elif scenario == "filename":
        s = _random_filename(r)
    elif scenario == "board_config":
        s = _random_board_config(r)
    elif scenario == "log_message":
        s = _random_log_message(r)
    elif scenario == "ip_config":
        s = _random_ip_config_snippet(r)
    elif scenario == "ascii_blob":
        s = _rand_ascii(r, _rand_int(r, 1, min(256, MAX_LEN)))
    elif scenario == "unicode_blob":
        # Keep shorter to avoid surpassing size when encoded
        s = _rand_unicode(r, _rand_int(r, 1, 128))
    else:  # prebaked
        s = r.choice(_prebaked_cases())

    # Optionally decorate with realistic prefixes/suffixes to hit more paths
    if r.random() < 0.25:
        prefix = r.choice(["", "INFO: ", "WARN: ", "ERR: ", "cfg:", "param:"])
        s = prefix + s
    if r.random() < 0.2:
        suffix = r.choice(["", "\n", "\r\n", " END", " !"])
        s = s + suffix

    # Bound size and ensure it's valid UTF-8 encoding when needed; for arbitrary string we can return raw bytes.
    # Encode as UTF-8; if surrogates sneak in, replace to keep a valid C-string when used.
    b = s.encode('utf-8', errors='replace')
    if len(b) > 4096:
        b = b[:4096]

    return bytes(b)

import random
import io

def _rand_bool(rnd):
    return rnd.random() < 0.5

def _choose(rnd, choices):
    return choices[rnd.randrange(len(choices))]

def _gen_number(rnd):
    # Generate a variety of numeric literals parsers usually accept
    kinds = [
        lambda: f"{rnd.uniform(-1e6, 1e6):.6f}",
        lambda: str(rnd.randint(-10**9, 10**9)),
        lambda: f"{rnd.uniform(-1e-6, 1e-6):.12e}",
        lambda: "nan",
        lambda: "+inf",
        lambda: "-inf",
    ]
    # Bias toward normal finite numbers but include special tokens sometimes
    if rnd.random() < 0.85:
        return _choose(rnd, kinds[:3])()
    return _choose(rnd, kinds)()

def _gen_delim(rnd):
    # Common delimiters DataFilter.read_file is likely to accept
    return _choose(rnd, [",", "\t", " ", ";", "|"])

def _gen_line_ending(rnd):
    return _choose(rnd, ["\n", "\r\n", "\r"])  # cover different platforms

def _gen_comment_prefix(rnd):
    # Many numeric readers skip comment lines that start with these
    return _choose(rnd, ["#", "%", ";;", "//"])  # include INI/MATLAB/CSV styles

def _gen_header(rnd, cols, delim):
    parts = []
    # Optionally prepend a comment header with column names
    if _rand_bool(rnd):
        prefix = _gen_comment_prefix(rnd)
        names = [f"c{i+1}" for i in range(cols)]
        parts.append(prefix + " " + delim.join(names) + _gen_line_ending(rnd))
    # Optionally include dimensions as a comment
    if rnd.random() < 0.3:
        prefix = _gen_comment_prefix(rnd)
        parts.append(prefix + f" shape={cols}x?" + _gen_line_ending(rnd))
    return "".join(parts)

def _gen_row(rnd, cols, delim):
    row = []
    for c in range(cols):
        # Occasionally insert blank fields which some parsers treat as NaN
        if rnd.random() < 0.03:
            row.append("")
        else:
            row.append(_gen_number(rnd))
    # Optionally add trailing delimiter
    s = delim.join(row)
    if rnd.random() < 0.1:
        s += delim
    return s

def _gen_block(rnd, rows, cols, delim, line_end):
    lines = []
    for r in range(rows):
        # Randomly insert comment or blank lines between data
        if rnd.random() < 0.05:
            lines.append(_gen_comment_prefix(rnd) + " random" + line_end)
        elif rnd.random() < 0.05:
            lines.append(line_end)
        lines.append(_gen_row(rnd, cols, delim) + line_end)
    return "".join(lines)

def _gen_matrix_text(rnd):
    # Choose a layout: CSV/TSV/space separated or mixed
    use_mixed = rnd.random() < 0.15
    base_delim = _gen_delim(rnd)
    line_end = _gen_line_ending(rnd)

    # Choose size bounded to keep <=4096 bytes
    cols = rnd.randint(1, 16)
    rows = rnd.randint(1, 128 // max(cols, 1))

    header = _gen_header(rnd, cols, base_delim)

    buf = io.StringIO()
    buf.write(header)

    if use_mixed:
        # Mix delimiters row-by-row to exercise robust tokenization
        for r in range(rows):
            delim = _gen_delim(rnd) if rnd.random() < 0.7 else base_delim
            # Occasionally wrap row in brackets often seen in MATLAB/Octave dumps
            wrap = rnd.random() < 0.1
            line = _gen_row(rnd, cols, delim)
            if wrap:
                line = "[" + line + "]"
            buf.write(line + line_end)
    else:
        buf.write(_gen_block(rnd, rows, cols, base_delim, line_end))

    # Optionally append a footer comment or trailing newline variety
    if rnd.random() < 0.3:
        buf.write(_gen_comment_prefix(rnd) + " end" + line_end)
    if rnd.random() < 0.5:
        buf.write(line_end)

    text = buf.getvalue()
    # Ensure size limit; if too large, truncate at last newline to keep valid lines
    b = text.encode("utf-8", errors="ignore")
    if len(b) > 4096:
        cut = b[:4096]
        # try to end at a newline
        nl = cut.rfind(b"\n")
        if nl != -1:
            cut = cut[:nl+1]
        b = cut
    return b

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    return _gen_matrix_text(rnd)
